INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8195, '我在寻找被称为「部族硬币」的力量典范。它们是祖尔格拉布的各类居民使用的货币，每一枚都蕴藏着微妙而强大的魔精。$B$B共有九种不同的硬币。其中一些是我的同胞们所追寻的，用来为赞达拉的英雄们换取各种护甲。若你手上有多余的，我可以用一枚荣誉徽记换取你三枚硬币。你可以用这些徽记找商人林沃沙换取物品，他为我们的英雄提供特别的装备。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I seek the Paragons of Power known as the Coins of the Tribes. They are the currency used 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8238, '我在寻找被称为「部族硬币」的力量典范。它们是祖尔格拉布的各类居民使用的货币，每一枚都蕴藏着微妙而强大的魔精。$B$B共有九种不同的硬币。其中一些是我的同胞们所追寻的，用来为赞达拉的英雄们换取各种护甲。若你手上有多余的，我可以用一枚荣誉徽记换取你三枚硬币。你可以用这些徽记找商人林沃沙换取物品，他为我们的英雄提供特别的装备。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I seek the Paragons of Power known as the Coins of the Tribes. They are the currency used 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8239, '我在寻找被称为「部族硬币」的力量典范。它们是祖尔格拉布的各类居民使用的货币，每一枚都蕴藏着微妙而强大的魔精。$B$B共有九种不同的硬币。其中一些是我的同胞们所追寻的，用来为赞达拉的英雄们换取各种护甲。若你手上有多余的，我可以用一枚荣誉徽记换取你三枚硬币。你可以用这些徽记找商人林沃沙换取物品，他为我们的英雄提供特别的装备。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I seek the Paragons of Power known as the Coins of the Tribes. They are the currency used 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8271, '本地的冰斧巨魔是残忍的野人，他们最乐意的事莫过于把我们的骨头丢进那锅恶心的炖菜里。$B$B我们必须让他们见识我们的力量！$B$B我们从他们的洞窟里找回了记载其首领层级的典籍。这些古物显示，他们的首领「血怒者科尔拉克」惯于隐藏自己，直到有了现身的理由。$B$B科尔拉克死，冰斧部族便亡！杀了他再回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The indigenous Winterax trolls of the region are ruthless savages that would love nothing 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8272, '入侵的雷矛并非此地唯一的威胁，士兵。山谷中的战争在两条战线上进行。食人的冰斧巨魔同样在争夺权力。$B$B他们的首领是「血怒者科尔拉克」——一头残忍而狡诈的野兽。$B$B对科尔拉克的一击，可能就是击垮冰斧部族的沉重打击。杀掉那畜生，你会得到奖赏！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The invading Stormpike are not the only threat in the region, soldier. The war in the Vall
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8383, '奥特兰克山谷的战斗仍在继续，$N！近来你可尽了自己的一份力，$N？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The Battle in Alterac Valley rages on, $N! Have you done your part as of late, $N?
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8384, '打赢一场战争，不只是比对手更聪明、更能打。胜负往往就取决于谁能造出更多的军备。$B$B我们在阿拉希盆地拥有的，是可供先夺下的一方使用的大量资源。$B$B若联盟获胜，我们的部队就能多出许多刀剑与长矛。若部落获胜，那些刀剑和长矛照样会被造出来——只是矛头会对准我们！现在正是为联盟在阿拉希盆地出力的时候，$N。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Winning a war is about more than just outsmarting and outfighting your opponent. Victory o
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8385, '啊，$N。我希望你继续把经验带到各个战场上去。我们许多前线的将士都敬仰你这样久经沙场的老兵。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Ah, $N. I hope you continue to lend your experience to the different battlefronts. A lot o
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8386, '银翼哨兵与战歌先锋之间的战争，源于兽人对森林的破坏。不过，要保卫这片森林的理由远不止热爱自然。$B$B这片森林构成了一道战略屏障，使灰谷能够抵御大规模进攻。没有它，阿斯特兰纳撑不过一两天就会被并入贫瘠之地。$B$B为对抗战歌先锋尽你的一份力，$N！为了联盟！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8387, '奥特兰克的战斗仍在继续！你必须重返奥特兰克山谷，再次把入侵者逐出霜狼的领地，$N！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The battle for Alterac rages on! You must return to Alterac Valley and once more drive the
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8388, '许多勇敢的战士都仰望着你，$N。在与联盟的战斗中，你始终是众人的榜样。你此番远行带来了什么消息？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Many brave fighters look up to you, $N. You continue to be an example for all in the fight
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8389, '在战歌峡谷中与银翼哨兵的这场战斗至关重要。联盟打着保护一片本不属于他们的森林的幌子，企图夺走部落最大的一处木材来源。$B$B别让他们的图谋得逞，$N！带着你为部落建功的凭证回来见我！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The battle in Warsong Gulch against the Silverwing Sentinels is of great importance. Under
